# Generated by Claudian.
"""AppleScript bridge.

Two things every function here depends on:

TIMEOUTS — `osascript` can block indefinitely.  It waits on the Automation
permission dialog the first time you target a new app, and it hangs outright
if the target app is beachballing or System Events is wedged.  These calls
run on a shared 4-worker thread pool (`multitasking.async_executor`), so an
untimed hang permanently burns a worker; four of them deadlock every skill
in the assistant.  Every subprocess call below is bounded.

ESCAPING — script text is built by interpolating values that originate from
speech transcription and LLM entity extraction.  Interpolating them raw let
a value containing a double quote terminate the string literal and have the
remainder parsed as executable AppleScript.  It also broke ordinary use: any
notification whose message contained an apostrophe or quote failed with a
syntax error.  `_q()` quotes and escapes every interpolated value.
"""

from __future__ import annotations

import os
import subprocess

from utils.logger import get_logger

logger = get_logger(__name__)

# Generous enough for a slow app launch, short enough that a wedged
# osascript frees its worker instead of holding it forever.
DEFAULT_TIMEOUT = 12


def _q(value: str) -> str:
    """Render `value` as a safe AppleScript string literal, quotes included.

    AppleScript string literals escape with a backslash, so backslash must be
    doubled first or it would escape our own escaping.
    """
    escaped = str(value).replace("\\", "\\\\").replace('"', '\\"')
    return f'"{escaped}"'


def run(script: str, timeout: int = DEFAULT_TIMEOUT) -> tuple[bool, str]:
    try:
        result = subprocess.run(
            ["osascript", "-e", script],
            capture_output=True,
            text=True,
            timeout=timeout,
        )
    except subprocess.TimeoutExpired:
        logger.warning(f"AppleScript timed out after {timeout}s: {script[:80]}")
        return False, "timed out"
    except Exception as e:
        logger.error(f"AppleScript failed to launch: {e}")
        return False, str(e)

    success = result.returncode == 0
    output = result.stdout.strip() if success else result.stderr.strip()
    if not success:
        logger.debug(f"AppleScript failed: {output}\nScript: {script[:100]}")
    return success, output


def run_file(path: str, timeout: int = DEFAULT_TIMEOUT) -> tuple[bool, str]:
    try:
        result = subprocess.run(
            ["osascript", path], capture_output=True, text=True, timeout=timeout
        )
    except subprocess.TimeoutExpired:
        logger.warning(f"AppleScript file timed out: {path}")
        return False, "timed out"
    except Exception as e:
        return False, str(e)
    return result.returncode == 0, result.stdout.strip()


# ── Applications ─────────────────────────────────────────────────────────────

def open_application(app_name: str) -> tuple[bool, str]:
    return run(f"tell application {_q(app_name)} to activate")


def quit_application(app_name: str) -> tuple[bool, str]:
    return run(f"tell application {_q(app_name)} to quit")


def is_app_running(app_name: str) -> bool:
    script = (
        'tell application "System Events" to return '
        f"(name of processes) contains {_q(app_name)}"
    )
    ok, out = run(script)
    return ok and "true" in out.lower()


def get_frontmost_app() -> str:
    script = (
        'tell application "System Events" to get name of '
        "first process whose frontmost is true"
    )
    ok, out = run(script)
    return out if ok else ""


# ── Volume ───────────────────────────────────────────────────────────────────

def set_volume(level: int):
    level = max(0, min(100, int(level)))
    return run(f"set volume output volume {level}")


def get_volume() -> int:
    ok, out = run("get volume settings")
    if ok and "output volume:" in out:
        try:
            return int(out.split("output volume:")[1].split(",")[0].strip())
        except (ValueError, IndexError):
            pass
    return -1


def mute_volume():
    return run("set volume with output muted")


def unmute_volume():
    return run("set volume without output muted")


# ── System ───────────────────────────────────────────────────────────────────

def take_screenshot(path: str = "~/Desktop/screenshot.png"):
    # subprocess runs without a shell, so `~` is NOT expanded — passing it
    # through raw would create a literal directory named "~".
    resolved = os.path.expanduser(path)
    try:
        result = subprocess.run(
            ["screencapture", "-x", resolved], capture_output=True, timeout=20
        )
    except subprocess.TimeoutExpired:
        logger.warning("screencapture timed out")
        return False, resolved
    return result.returncode == 0, resolved


def lock_screen():
    script = (
        'tell application "System Events" to keystroke "q" '
        "using {command down, control down}"
    )
    return run(script)


def empty_trash():
    return run('tell application "Finder" to empty trash', timeout=30)


def show_notification(title: str, message: str, subtitle: str = ""):
    parts = [f"display notification {_q(message)}", f"with title {_q(title)}"]
    if subtitle:
        parts.append(f"subtitle {_q(subtitle)}")
    return run(" ".join(parts))
